import java.util.*;

class Solution {
    private boolean[][] rows = new boolean[9][10], cols = new boolean[9][10], boxes = new boolean[9][10];
    private List<int[]> empty = new ArrayList<>();

    public void fillPuzzle(char[][] board) {
        for (int r = 0; r < 9; r++)
            for (int c = 0; c < 9; c++) {
                if (board[r][c] == '.') { empty.add(new int[]{r, c}); continue; }
                int d = board[r][c] - '0';
                rows[r][d] = cols[c][d] = boxes[r / 3 * 3 + c / 3][d] = true;
            }
        solve(board, 0);
    }

    private boolean solve(char[][] board, int k) {
        if (k == empty.size()) return true;            // every blank filled
        int r = empty.get(k)[0], c = empty.get(k)[1], b = r / 3 * 3 + c / 3;
        for (int d = 1; d <= 9; d++) {
            if (rows[r][d] || cols[c][d] || boxes[b][d]) continue;
            board[r][c] = (char) ('0' + d);
            rows[r][d] = cols[c][d] = boxes[b][d] = true;
            if (solve(board, k + 1)) return true;
            rows[r][d] = cols[c][d] = boxes[b][d] = false;   // undo
        }
        board[r][c] = '.';
        return false;
    }
}

