function fillPuzzle(board) {
  const rows = new Int32Array(9), cols = new Int32Array(9), box = new Int32Array(9), empt = [];
  for (let i = 0; i < 9; i++) for (let j = 0; j < 9; j++) {
    const c = board[i][j];
    if (c === ".") empt.push(i * 9 + j);
    else { const b = 1 << Number(c); rows[i] |= b; cols[j] |= b; box[((i / 3) | 0) * 3 + ((j / 3) | 0)] |= b; }
  }
  const pc = m => { let c = 0; while (m) { m &= m - 1; c++; } return c; };
  function go(n) { // empt[0..n) are still empty
    if (n === 0) return true;
    let best = -1, bm = 0, bc = 10;
    for (let t = 0; t < n; t++) {
      const p = empt[t], i = (p / 9) | 0, j = p % 9;
      const m = 0x3FE & ~(rows[i] | cols[j] | box[((i / 3) | 0) * 3 + ((j / 3) | 0)]), c = pc(m);
      if (c < bc) { bc = c; best = t; bm = m; if (c <= 1) break; }
    }
    if (bc === 0) return false;
    const p = empt[best]; empt[best] = empt[n - 1]; empt[n - 1] = p;
    const i = (p / 9) | 0, j = p % 9, k = ((i / 3) | 0) * 3 + ((j / 3) | 0);
    for (let d = 1; d <= 9; d++) {
      const b = 1 << d; if (!(bm & b)) continue;
      rows[i] |= b; cols[j] |= b; box[k] |= b; board[i][j] = String(d);
      if (go(n - 1)) return true;
      rows[i] ^= b; cols[j] ^= b; box[k] ^= b;
    }
    board[i][j] = "."; empt[n - 1] = empt[best]; empt[best] = p;
    return false;
  }
  go(empt.length);
}
